import { expect, expectStatus, test } from "../../fixtures";

test("A vendor under review cannot be edited", { tag: "@VEN-09" }, async ({ apiAs, factory }) => {
  // Arrange: a vendor in status "in_review", submitted by a member
  const { vendor } = await factory.vendorInReview({ as: "member" });
  const member = await apiAs("member");
  const before = await expectStatus(await member.get(`/api/vendors/${vendor.id}`), 200);
  const originalEmail = before.contact_email;

  // Act
  const response = await member.patch(`/api/vendors/${vendor.id}`, {
    data: { contact_email: "billing@acmefreight.example" },
  });

  // Assert
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("vendor_locked");

  // Re-read the stored record: the refused edit must not have been saved.
  const stored = await expectStatus(await member.get(`/api/vendors/${vendor.id}`), 200);
  expect(stored.status).toBe("in_review");
  expect(stored.contact_email).toBe(originalEmail);
  expect(stored.contact_email).not.toBe("billing@acmefreight.example");
});
